    remainder_positions = {}
    while remainder != 0:
        if remainder in remainder_positions:
            # Insert parentheses for repeating part
            res.insert(remainder_positions[remainder], '(')
            res.append(')')
            break
        remainder_positions[remainder] = len(res)
        remainder *= 10
        res.append(str(remainder // denominator))
